content.css:
.northstar-date {
  font: 12px 'Segoe UI', Arial, sans-serif;
  color: #23434b;
  padding: 10px 14px;
  box-sizing: border-box;
  overflow: auto;
  height: 100%;
  background: white;
  border: 1px solid #e1e7eb;
  border-radius: 8px;
}
.date-row {
  display: flex;
  align-items: center;
  gap: 28px;
  flex-wrap: wrap;
}
.date-tabs {
  display: flex;
  gap: 3px;
  background: #f0f4f5;
  border-radius: 6px;
  padding: 3px;
}
button {
  cursor: pointer;
  font: inherit;
  border: 1px solid #dce5e8;
  border-radius: 5px;
  padding: 8px 12px;
  background: #f5f8f8;
  color: #28545a;
  white-space: nowrap;
}
.date-tabs button {
  border: 0;
  background: none;
  padding: 9px 17px;
}
.date-tabs button.selected {
  background: #234b57;
  color: white;
}
button:disabled {
  opacity: 0.35;
  cursor: default;
}
.date-picker {
  display: flex;
  gap: 8px;
  align-items: center;
}
.date-picker select,
.date-picker input {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid #dce5e8;
  border-radius: 5px;
  color: #264a53;
  background: #fff;
}
.date-picker select {
  min-width: 210px;
}
.date-picker label {
  display: flex;
  align-items: center;
  gap: 8px;
}
.date-note {
  font-size: 11px;
  color: #71828d;
  margin-top: 10px;
}
.date-note.error {
  color: #b45438;
}
